package cn.yueji.balance;
import android.graphics.Rect;import android.view.*;import android.widget.*;import android.os.SystemClock;import androidx.test.ext.junit.runners.AndroidJUnit4;import org.junit.*;import org.junit.runner.RunWith;import java.io.*;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class)
public class V473UiTest {
 final V470UiTest old=new V470UiTest();final V43UiTest h=old.h;final YuejiTest t=old.t;
 @Before public void before(){old.before();t.context.getSharedPreferences("updates",0).edit().putString("guideRead",UsageGuideActivity.REVISION).putLong("lastOpenedBuild",26).commit();}
 @After public void after()throws Exception{old.after();}
 View desc(String value){return h.desc(t.app.root,value);}
 void detail(){t.start(old.sample());t.ui(()->t.app.watchScreens.open("006431"));}
 void shot(String name){old.shot("v473-"+name+".png");}
 @Test public void batchNamesRemainVisibleAndToolbarDoesNotScroll(){t.start(old.sample());t.ui(()->{t.app.watchScreens.activeGroup="短债";t.app.go("fund_watchlist");desc("自选基金006431").performLongClick();});t.ui(()->{assertNotNull(t.findText(t.app.body,"汇安鼎利纯债债券A"));View name=t.findText(t.app.body,"汇安鼎利纯债债券A");Rect bounds=new Rect();assertTrue(name.getGlobalVisibleRect(bounds));assertTrue(bounds.width()>t.app.dp(60));assertTrue(bounds.height()>t.app.dp(10));View bar=desc("自选批量操作栏");assertSame(t.app.root,bar.getParent());int[] before=new int[2];bar.getLocationOnScreen(before);ScrollView scroll=(ScrollView)t.app.body.getParent();scroll.scrollTo(0,1000);int[] after=new int[2];bar.getLocationOnScreen(after);assertEquals(before[1],after[1]);assertNotNull(t.findText(bar,"添加到"));assertNotNull(t.findText(bar,"删除"));CheckBox check=(CheckBox)desc("选择基金006431");check.setChecked(false);assertFalse(t.app.watchScreens.selectedCodes.contains("006431"));check.setChecked(true);assertTrue(t.app.watchScreens.selectedCodes.contains("006431"));});shot("batch");}
 @Test public void chartPeriodSelectionAndHorizontalOffsetPersist(){detail();t.ui(()->t.app.watchScreens.detailPeriods.fullScroll(View.FOCUS_RIGHT));SystemClock.sleep(200);final int[] offset={0};t.ui(()->{offset[0]=t.app.watchScreens.detailPeriods.getScrollX();assertTrue(offset[0]>0);desc("绘图周期成立来").performClick();});SystemClock.sleep(250);t.ui(()->{assertEquals(9,t.app.watchScreens.detailRange);assertEquals(offset[0],t.app.watchScreens.detailPeriods.getScrollX());desc("绘图周期近10年").performClick();});SystemClock.sleep(250);t.ui(()->{assertEquals(7,t.app.watchScreens.detailRange);assertEquals(offset[0],t.app.watchScreens.detailPeriods.getScrollX());});shot("period");}
 @Test public void feesHaveOneHeaderAndSeparateBoldOrangeDiscountColumn(){detail();t.ui(()->{Ledger.WatchFund f=t.app.watchScreens.find("006431");LinearLayout card=t.app.col();t.app.watchScreens.feeRows(card,"买入费率","适用金额  原费率  天天基金优惠费率\n小于100万元  0.80%  0.08%\n大于等于100万元，小于300万元  0.50%  0.05%\n大于等于500万元  每笔1000元");assertNull(t.findText(card,"天天基金优惠费率"));TextView discount=(TextView)t.findText(card,"0.08%");assertNotNull(discount);assertTrue(discount.getTypeface().isBold());assertEquals(0xFFE87920,discount.getCurrentTextColor());assertNotNull(t.findText(card,"每笔1000元"));assertEquals("小于100万元",((TextView)((LinearLayout)discount.getParent()).getChildAt(0)).getText().toString());});t.ui(()->{Ledger.Data c=t.app.copy();c.watchFunds.get(0).profile.buyRules="适用金额  原费率  天天基金优惠费率\n小于100万元  0.80%  0.08%\n大于等于100万元，小于300万元  0.50%  0.05%\n大于等于500万元  每笔1000元";t.app.commit(c);t.app.watchScreens.rulesExpanded=true;t.app.render();});SystemClock.sleep(200);t.ui(()->((ScrollView)t.app.body.getParent()).fullScroll(View.FOCUS_DOWN));shot("fees");}
 @Test public void nestedCardsAreCompactAndSingleSurface(){t.start(old.sample());t.ui(()->{t.app.openTab(MainActivity.TAB_SETTINGS);View title=t.findText(t.app.body,"数据导入及导出备份管理");((View)title.getParent().getParent()).performClick();LinearLayout content=t.app.sectionContents.get("dataManagement");for(int i=1;i<content.getChildCount();i++){View child=content.getChildAt(i);assertEquals(0f,child.getElevation(),0);assertEquals(0,child.getPaddingTop());LinearLayout.LayoutParams p=(LinearLayout.LayoutParams)child.getLayoutParams();assertTrue(p.bottomMargin<=t.app.dp(4));assertTrue(p.topMargin<=t.app.dp(4));}});shot("settings-nested");}
 @Test public void ruleTabsKeepRootChartAndScrollPosition(){detail();t.ui(()->t.findText(t.app.body,"买入 / 卖出规则  ▾").performClick());SystemClock.sleep(200);t.ui(()->{View root=t.app.root,chart=h.first(t.app.body,WatchChart.class);ScrollView scroll=(ScrollView)t.app.body.getParent();int y=scroll.getScrollY();((Segmented)t.app.watchScreens.ruleTabs).setSelected(1);t.app.watchScreens.ruleTab=1;t.app.watchScreens.updateRuleContent();assertSame(root,t.app.root);assertSame(chart,h.first(t.app.body,WatchChart.class));assertEquals(y,scroll.getScrollY());});shot("rules-sell");}

 @Test public void permissionRowsBelongToSecurityAndInstallerUsesStableTarget(){t.start(old.sample());t.ui(()->{t.app.openTab(MainActivity.TAB_SETTINGS);LinearLayout security=t.app.sectionContents.get("security"),notify=t.app.sectionContents.get("notify");for(String label:new String[]{"系统通知权限","后台刷新与省电设置","安装应用权限"}){assertNotNull(label,t.findText(security,label));assertNull(label,t.findText(notify,label));}android.content.Intent launch=t.app.getPackageManager().getLaunchIntentForPackage(t.app.getPackageName());assertNotNull(launch);assertEquals("cn.yueji.balance.UpdateLaunchActivity",launch.getComponent().getClassName());});}
 @Test public void collapsedRulesFitPortraitSizes()throws Exception{for(String[] config:new String[][]{{"1080x1920","420"},{"1080x2400","420"},{"1260x2800","560"}}){t.device.executeShellCommand("wm size "+config[0]);t.device.executeShellCommand("wm density "+config[1]);detail();SystemClock.sleep(200);t.ui(()->{View rules=t.findText(t.app.body,"买入 / 卖出规则  ▾");Rect bounds=new Rect();assertTrue(rules.getGlobalVisibleRect(bounds));assertEquals(rules.getHeight(),bounds.height());assertNotNull(t.findText(t.app.body,"日涨跌幅\n"+t.app.watchScreens.find("006431").navDate));});shot("folded-"+config[0]);}t.device.executeShellCommand("wm size reset");t.device.executeShellCommand("wm density reset");}
}
